20	
21	function withParams(base: string, params: Record<string, string>): string {
22	  const u = new URL(base);
23	  u.searchParams.set("platform", "desktop");
24	  for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
25	  return u.toString();
26	}
27	
28	const local = await startLocalAiServer();
29	
30	const url = local
31	  ? withParams(BASE_URL, { localAi: "1", localPort: String(local.port) })
32	  : withParams(BASE_URL, {});
