/**
 * Needle 3 ABI harness — the make-or-break probe from the plan.
 *
 * Proves, outside any UI: weights load from memory, needle_embed reports its
 * dimension via a null out-pointer, and the resulting vectors rank related text
 * above unrelated text under cosine similarity.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;

const wasmBinary = readFileSync(DIR + "needle.wasm");
const cact = readFileSync(DIR + "needle3.cact");
console.log(`wasm ${wasmBinary.length}B · weights ${cact.length}B`);

const createNeedle = require(DIR + "needle.js");

const Module = await createNeedle({
  wasmBinary,
  noFSInit: true,
  print: () => {},
  printErr: (m) => {
    if (!/warn/i.test(m)) console.error("[needle]", m);
  },
});

const has = (k) => (typeof Module[k] !== "undefined" ? "yes" : "NO");
console.log(
  "exports:",
  ["_needle_load", "_needle_init", "_needle_embed", "_needle_complete", "_needle_reset", "_malloc", "HEAPU8"]
    .map((k) => `${k}=${has(k)}`)
    .join(" "),
);

/** Copy a JS buffer into wasm memory. Returns the pointer. */
function toWasm(buf) {
  const ptr = Module._malloc(buf.length);
  if (!ptr) throw new Error(`malloc(${buf.length}) failed`);
  Module.HEAPU8.set(buf, ptr);
  return ptr;
}

/** NUL-terminated C string into wasm memory. */
function cstr(s) {
  const bytes = Buffer.from(s + "\0", "utf8");
  return toWasm(bytes);
}

// --- load weights -----------------------------------------------------------
