cd /tmp/claude-1000/-home-diogenes-Projects-twyne/f9558bf0-27ae-41f5-873b-868109e5478e/scratchpad && cat > needle-toolscale.mjs <<'EOF'
/**
 * How does needle_init scale with declared tool count?
 * Decides whether the ~90-entry editor command catalogue can be declared as
 * Needle tools at all, or whether the command bar must run on embeddings.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;
const M = await (require(DIR + "needle.js"))({
  wasmBinary: readFileSync(DIR + "needle.wasm"), noFSInit: true, print: () => {}, printErr: () => {},
});
const toWasm = (b) => { const p = M._malloc(b.length); M.HEAPU8.set(b, p); return p; };
const cstr = (s) => toWasm(Buffer.from(s + "\0", "utf8"));
const cact = readFileSync(DIR + "needle3.cact");
M._needle_load(toWasm(cact), BigInt(cact.length));
const sys = cstr("You route editor commands.");

const mk = (n) => JSON.stringify(
  Array.from({ length: n }, (_, i) => ({
    name: `command_${i}`,
    description: `Editor command number ${i} which performs a distinct formatting or navigation action`,
    parameters: { type: "object", properties: { arg: { type: "string" } } },
  })),
);

console.log("tools   init_ms    ms/tool   rc");
const pts = [];
for (const n of [1, 2, 4, 8, 16, 32]) {
  const ptr = cstr(mk(n));
  // alternate away first so this is never a same-toolset no-op
  M._needle_init(sys, cstr(mk(n + 100)), 0);
  const t = performance.now();
  const rc = M._needle_init(sys, ptr, 0);
  const ms = performance.now() - t;
  pts.push([n, ms]);
  console.log(`${String(n).padStart(5)}  ${ms.toFixed(0).padStart(7)}  ${(ms / n).toFixed(0).padStart(8)}   ${rc}`);
}
const [n1, m1] = pts[0], [n2, m2] = pts.at(-1);
const slope = (m2 - m1) / (n2 - n1);
console.log(`\nslope ~${slope.toFixed(0)}ms per tool, intercept ~${(m1 - slope * n1).toFixed(0)}ms`);
console.log(`extrapolated for Twyne's ~90 editor commands: ${((slope * 90 + (m1 - slope * n1)) / 1000).toFixed(1)}s`);
EOF
