file.content:
/**
 * Does `tool_index_path` cache the tool index?
 *
 * The re-init probe showed a toolset switch costs ~174ms x tool_count -- the
 * cost of one embed per tool description. needle_init's third arg is a *path*,
 * which would be where that index is persisted. If passing one makes the second
 * init of the same toolset cheap, the 1.4s penalty is a first-run cost we can
 * pay at build time and ship, instead of an architectural ceiling.
 */
import { readFileSync, existsSync, statSync, rmSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;
const IDX = DIR + "toolidx";
rmSync(IDX, { recursive: true, force: true });
mkdirSync(IDX, { recursive: true });

// NOTE: no noFSInit here -- we need a filesystem for a path to mean anything.
const Module = await (require(DIR + "needle.js"))({
  wasmBinary: readFileSync(DIR + "needle.wasm"),
  print: () => {},
  printErr: (m) => console.error("[needle]", m),
});

const toWasm = (buf) => {
  const p = Module._malloc(buf.length);
  Module.HEAPU8.set(buf, p);
  return p;
};
const cstr = (s) => toWasm(Buffer.from(s + "\0", "utf8"));

const cact = readFileSync(DIR + "needle3.cact");
Module._needle_load(toWasm(cact), BigInt(cact.length));

// Mount the host dir so a real file can actually appear.
let mounted = "";
try {
  Module.FS.mkdir("/idx");
  Module.FS.mount(Module.FS.filesystems.NODEFS, { root: IDX }, "/idx");
  mounted = "/idx/commandbar.idx";
  console.log("NODEFS mounted at /idx");
} catch (e) {
  console.log("NODEFS mount failed:", e.message, "- falling back to MEMFS path");
  mounted = "/commandbar.idx";
}

const tools = JSON.stringify([
  { name: "run_command", description: "Run an editor command by id", parameters: { type: "object", properties: { id: { type: "string" } }, required: ["id"] } },
  { name: "search_commands", description: "Search the editor command catalogue", parameters: { type: "object", properties: { q: { type: "string" } }, required: ["q"] } },
  { name: "cancel", description: "Do nothing this turn", parameters: { type: "object", properties: {} } },
]);
const other = JSON.stringify([
  { name: "extract_claim", description: "Extract a factual claim needing a citation", parameters: { type: "object", properties: { text: { type: "string" } }, required: ["text"] } },
]);

const sys = cstr("You route editor commands.");
const sysO = cstr("You extract claims.");
const toolsPtr = cstr(tools);
const otherPtr = cstr(other);
const idxPtr = cstr(mounted);

const time = (fn) => {
  const t = performance.now();
  const rc = fn();
  return [performance.now() - t, rc];
};

const [t1, rc1] = time(() => Module._needle_init(sys, toolsPtr, idxPtr));
console.log(`init #1 with tool_index_path : ${t1.toFixed(1)}ms  (rc ${rc1})`);

// Switch away, so coming back cannot be a same-toolset no-op.
const [tAway] = time(() => Module._needle_init(sysO, otherPtr, 0));
console.log(`init (switch away, no path)  : ${tAway.toFixed(1)}ms`);

const [t2, rc2] = time(() => Module._needle_init(sys, toolsPtr, idxPtr));
console.log(`init #2 with tool_index_path : ${t2.toFixed(1)}ms  (rc ${rc2})`);

// Did anything get written?
let wrote = false;
try {
  const st = Module.FS.analyzePath(mounted);
  wrote = st.exists;
  console.log(`index file exists in wasm FS  : ${wrote}${wrote ? ` (${Module.FS.stat(mounted).size} bytes)` : ""}`);
} catch (e) {
  console.log("FS.analyzePath failed:", e.message);
}
if (existsSync(IDX + "/commandbar.idx")) {
  console.log(`index file on host disk       : ${statSync(IDX + "/commandbar.idx").size} bytes`);
}

console.log();
const speedup = t1 / t2;
console.log(
  t2 < t1 * 0.5
    ? `CACHED: second init ${speedup.toFixed(1)}x faster -> ship a prebuilt tool index; the 1.4s is a build-time cost.`
    : `NOT CACHED: no meaningful speedup (${speedup.toFixed(2)}x) -> one merged toolset, initialized once.`,
);

/**
 * Verification step 2 — re-init cost.
 *
 * needle.h: one process-global, non-thread-safe model, one toolset per
 * needle_init; needle_reset clears history but keeps tools. If switching
 * toolsets is cheap, needle-runtime.ts can serialize jobs from every surface
 * through one model. If it is expensive, the toolsets must be merged into one
 * catalogue -- which collides with the tool-retrieval head rendering only the
 * top 5 tools per turn.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;
const Module = await (require(DIR + "needle.js"))({
  wasmBinary: readFileSync(DIR + "needle.wasm"),
  noFSInit: true,
  print: () => {},
  printErr: () => {},
});

const toWasm = (buf) => {
  const p = Module._malloc(buf.length);
  Module.HEAPU8.set(buf, p);
  return p;
};
const cstr = (s) => toWasm(Buffer.from(s + "\0", "utf8"));

const cact = readFileSync(DIR + "needle3.cact");
let t = performance.now();
Module._needle_load(toWasm(cact), BigInt(cact.length));
console.log(`needle_load (35 MB): ${(performance.now() - t).toFixed(1)}ms  [once per process]`);

// Two genuinely different toolsets, standing in for two Twyne surfaces.
const commandBarTools = JSON.stringify([
  { name: "run_command", description: "Run an editor command", parameters: { type: "object", properties: { id: { type: "string" } }, required: ["id"] } },
  { name: "search_commands", description: "Search the command catalogue", parameters: { type: "object", properties: { q: { type: "string" } }, required: ["q"] } },
]);
const researchTools = JSON.stringify([
  { name: "extract_claim", description: "Extract a factual claim needing a citation", parameters: { type: "object", properties: { text: { type: "string" }, confidence: { type: "number" } }, required: ["text"] } },
  { name: "rank_source", description: "Rate how well a source supports a claim", parameters: { type: "object", properties: { source_id: { type: "string" }, relevance: { type: "number" } }, required: ["source_id", "relevance"] } },
  { name: "skip", description: "No claim in this passage", parameters: { type: "object", properties: {} } },
]);

const sysA = cstr("You route editor commands.");
const sysB = cstr("You extract research claims.");
const toolsA = cstr(commandBarTools);
const toolsB = cstr(researchTools);

function timeIt(label, fn, n = 5) {
  const runs = [];
  for (let i = 0; i < n; i++) {
    const t0 = performance.now();
    fn();
    runs.push(performance.now() - t0);
  }
  runs.sort((a, b) => a - b);
  console.log(`${label.padEnd(34)} median ${runs[Math.floor(n / 2)].toFixed(2)}ms  (min ${runs[0].toFixed(2)}, max ${runs.at(-1).toFixed(2)})`);
  return runs[Math.floor(n / 2)];
}

console.log();
const cold = performance.now();
Module._needle_init(sysA, toolsA, 0);
console.log(`first needle_init:                 ${(performance.now() - cold).toFixed(2)}ms`);

const same = timeIt("re-init, SAME toolset", () => Module._needle_init(sysA, toolsA, 0));
let flip = 0;
const alt = timeIt("re-init, ALTERNATING toolsets", () => {
  flip ^= 1;
  Module._needle_init(flip ? sysB : sysA, flip ? toolsB : toolsA, 0);
});
const reset = timeIt("needle_reset", () => Module._needle_reset());

console.log();
const dim = Module._needle_embed(cstr("probe"), 0, 0);
const embedPtr = Module._malloc(dim * 4);
const embedIn = cstr("A representative sentence of roughly the length Twyne would embed.");
const emb = timeIt("needle_embed", () => Module._needle_embed(embedIn, embedPtr, dim), 7);

console.log();
console.log(`Toolset switch costs ${alt.toFixed(2)}ms vs ${same.toFixed(2)}ms for a no-op re-init`);
console.log(`and ${(alt / emb).toFixed(1)}x a single embed (${emb.toFixed(2)}ms).`);
console.log(
  alt < 50
    ? "VERDICT: cheap -> serialized job queue across surfaces is viable; keep toolsets separate."
    : "VERDICT: expensive -> merge toolsets into one catalogue, or pin one toolset per Worker.",
);

/**
 * Anisotropy probe. The ABI harness passed, but 0.9669 vs 0.9354 is a thin
 * margin near 1.0. If the whole space is crowded into a narrow cone, absolute
 * cosine thresholds are meaningless and only *rank* (and centered cosine)
 * carries signal. This measures that directly.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;
const Module = await (require(DIR + "needle.js"))({
  wasmBinary: readFileSync(DIR + "needle.wasm"),
  noFSInit: true,
  print: () => {},
  printErr: () => {},
});

function toWasm(buf) {
  const p = Module._malloc(buf.length);
  Module.HEAPU8.set(buf, p);
  return p;
}
const cstr = (s) => toWasm(Buffer.from(s + "\0", "utf8"));

const cact = readFileSync(DIR + "needle3.cact");
Module._needle_load(toWasm(cact), BigInt(cact.length));
Module._needle_init(cstr("You are a helpful assistant."), cstr("[]"), 0);
const dim = Module._needle_embed(cstr("probe"), 0, 0);

function embed(text) {
  const inPtr = cstr(text);
  const outPtr = Module._malloc(dim * 4);
  Module._needle_embed(inPtr, outPtr, dim);
  const out = Float32Array.from(new Float32Array(Module.HEAPU8.buffer, outPtr, dim));
  Module._free(inPtr);
  Module._free(outPtr);
  return out;
}

const cos = (a, b) => {
  let d = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return d / (Math.sqrt(na) * Math.sqrt(nb) || 1);
};

// Deliberately unrelated topics — a well-spread space should score these low.
const corpus = [
  "Qualified immunity shields officials from civil suits unless clearly established law was violated.",
  "The Fourth Amendment governs searches and seizures by state actors.",
  "Sourdough starter needs feeding every twelve hours at room temperature.",
  "Braising short ribs requires three hours at 300 degrees Fahrenheit.",
  "The tarsier's eyes are each as large as its entire brain.",
  "Photosynthesis converts light energy into chemical energy in chloroplasts.",
  "Rust's borrow checker enforces memory safety without a garbage collector.",
  "TCP uses a three-way handshake to establish a connection.",
];
const vecs = corpus.map(embed);

// Pairwise distribution across the whole (deliberately diverse) set.
const sims = [];
for (let i = 0; i < vecs.length; i++)
  for (let j = i + 1; j < vecs.length; j++) sims.push(cos(vecs[i], vecs[j]));
sims.sort((a, b) => a - b);
const mean = sims.reduce((a, b) => a + b, 0) / sims.length;
const sd = Math.sqrt(sims.reduce((a, b) => a + (b - mean) ** 2, 0) / sims.length);

console.log(`dim ${dim} · ${sims.length} unrelated-ish pairs`);
console.log(`raw cosine  min ${sims[0].toFixed(4)}  mean ${mean.toFixed(4)}  max ${sims.at(-1).toFixed(4)}  sd ${sd.toFixed(4)}`);

// Centered cosine: subtract the corpus mean vector, the standard anisotropy fix.
const mu = new Float32Array(dim);
for (const v of vecs) for (let i = 0; i < dim; i++) mu[i] += v[i] / vecs.length;
const centered = vecs.map((v) => Float32Array.from(v, (x, i) => x - mu[i]));
const csims = [];
for (let i = 0; i < centered.length; i++)
  for (let j = i + 1; j < centered.length; j++) csims.push(cos(centered[i], centered[j]));
csims.sort((a, b) => a - b);
const cmean = csims.reduce((a, b) => a + b, 0) / csims.length;
const csd = Math.sqrt(csims.reduce((a, b) => a + (b - cmean) ** 2, 0) / csims.length);
console.log(`centered    min ${csims[0].toFixed(4)}  mean ${cmean.toFixed(4)}  max ${csims.at(-1).toFixed(4)}  sd ${csd.toFixed(4)}`);

// Does ranking actually work? Query each doc with a paraphrase, expect rank 1.
const probes = [
  ["Can police officers be sued personally for constitutional violations?", 0],
  ["How often should I feed my bread starter?", 2],
  ["Which primate has enormous eyes relative to its skull?", 4],
  ["How does Rust avoid needing a garbage collector?", 6],
];
let top1 = 0;
for (const [q, want] of probes) {
  const qv = embed(q);
  const ranked = vecs
    .map((v, i) => ({ i, s: cos(qv, v) }))
    .sort((a, b) => b.s - a.s);
  const hit = ranked[0].i === want;
  if (hit) top1++;
  console.log(
    `${hit ? "ok  " : "MISS"} "${q.slice(0, 44)}…" -> #${ranked[0].i} (${ranked[0].s.toFixed(4)}), want #${want}; gap to #2 = ${(ranked[0].s - ranked[1].s).toFixed(4)}`,
  );
}
console.log(`\nretrieval top-1: ${top1}/${probes.length}`);

/**
 * Needle 3 ABI harness — the make-or-break probe from the plan.
 *
 * Proves, outside any UI: weights load from memory, needle_embed reports its
 * dimension via a null out-pointer, and the resulting vectors rank related text
 * above unrelated text under cosine similarity.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const DIR = new URL(".", import.meta.url).pathname;

const wasmBinary = readFileSync(DIR + "needle.wasm");
const cact = readFileSync(DIR + "needle3.cact");
console.log(`wasm ${wasmBinary.length}B · weights ${cact.length}B`);

const createNeedle = require(DIR + "needle.js");

const Module = await createNeedle({
  wasmBinary,
  noFSInit: true,
  print: () => {},
  printErr: (m) => {
    if (!/warn/i.test(m)) console.error("[needle]", m);
  },
});

const has = (k) => (typeof Module[k] !== "undefined" ? "yes" : "NO");
console.log(
  "exports:",
  ["_needle_load", "_needle_init", "_needle_embed", "_needle_complete", "_needle_reset", "_malloc", "HEAPU8"]
    .map((k) => `${k}=${has(k)}`)
    .join(" "),
);

/** Copy a JS buffer into wasm memory. Returns the pointer. */
function toWasm(buf) {
  const ptr = Module._malloc(buf.length);
  if (!ptr) throw new Error(`malloc(${buf.length}) failed`);
  Module.HEAPU8.set(buf, ptr);
  return ptr;
}

/** NUL-terminated C string into wasm memory. */
function cstr(s) {
  const bytes = Buffer.from(s + "\0", "utf8");
  return toWasm(bytes);
}

// --- load weights -----------------------------------------------------------
const cactPtr = toWasm(cact);
let loaded;
try {
  // `unsigned long long n` — try BigInt first (WASM_BIGINT builds), then i32.
  loaded = Module._needle_load(cactPtr, BigInt(cact.length));
} catch {
  loaded = Module._needle_load(cactPtr, cact.length);
}
console.log("needle_load ->", loaded);
if (loaded < 0) {
  console.error("FAIL: weights did not load");
  process.exit(1);
}

// --- init -------------------------------------------------------------------
const sys = cstr("You are a helpful assistant.");
const tools = cstr("[]");
const initRc = Module._needle_init(sys, tools, 0);
console.log("needle_init ->", initRc);

// --- embedding dimension ----------------------------------------------------
const probe = cstr("dimension probe");
const dim = Module._needle_embed(probe, 0, 0);
console.log("embedding dim ->", dim);
if (dim <= 0) {
  console.error("FAIL: no embedding dimension");
  process.exit(1);
}

// --- embed ------------------------------------------------------------------
function embed(text) {
  const inPtr = cstr(text);
  const outPtr = Module._malloc(dim * 4);
  const rc = Module._needle_embed(inPtr, outPtr, dim);
  if (rc < 0) throw new Error(`needle_embed failed rc=${rc}`);
  // HEAPF32 is not exported, and the view must be re-derived after any growth.
  const view = new Float32Array(Module.HEAPU8.buffer, outPtr, dim);
  const out = Float32Array.from(view);
  Module._free(inPtr);
  Module._free(outPtr);
  return out;
}

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}

const query = "qualified immunity shields government officials from lawsuits";
const related = "The doctrine protects police officers from civil liability claims.";
const unrelated = "Sourdough starter needs feeding every twelve hours.";

const t0 = Date.now();
const [qv, rv, uv] = [query, related, unrelated].map(embed);
const ms = Date.now() - t0;

const simRelated = cosine(qv, rv);
const simUnrelated = cosine(qv, uv);

console.log(`\n3 embeddings in ${ms}ms (${(ms / 3).toFixed(0)}ms each)`);
console.log("cosine(query, related)   =", simRelated.toFixed(4));
console.log("cosine(query, unrelated) =", simUnrelated.toFixed(4));

const pass = simRelated > simUnrelated;
console.log(pass ? "\nPASS — related ranks above unrelated" : "\nFAIL — ordering is wrong");
process.exit(pass ? 0 : 1);

