import { describe, expect, test } from "bun:test";
import { SPINE_CRITERIA, type RubricCriterionSpec } from "../types";
import { defaultCriteriaSpecs } from "./rubric-criteria";
import {
  DEFAULT_THRESHOLDS,
  SCORE_LEVELS,
  buildRubricQuestions,
  buildRubricState,
  driftedKeys,
  gradeScores,
  readRubricAnswers,
  viewRubricGrade,
  type RubricGrade,
} from "./rubric-grade";
import type { ScoreAnswer, SystemOneAnswer } from "./system-one";

const answer = (
  value: number,
  confidence: number,
  probabilities?: Record<string, number>,
): ScoreAnswer => ({
  type: "score",
  score: value,
  legend: Object.fromEntries(SCORE_LEVELS.map((l, i) => [String(i), l])),
  probabilities: probabilities ?? { "0": 0, "1": 0, "2": 1, "3": 0, "4": 0 },
  confidence,
});

const gradeOf = (answers: Record<string, SystemOneAnswer>): RubricGrade =>
  readRubricAnswers(answers, {
    model: "jev-1.13.0",
    usage: { input_tokens: 1401, output_tokens: 300 },
  });

describe("buildRubricQuestions", () => {
  test("one Score per enabled criterion", () => {
    const questions = buildRubricQuestions(defaultCriteriaSpecs());
    for (const q of Object.values(questions)) {
      expect(q.type).toBe("score");
      expect(q.criteria).toEqual(SCORE_LEVELS);
    }
  });

  test("excludes engagement, which is derived from the grade it would feed", () => {
    expect(
      buildRubricQuestions(defaultCriteriaSpecs()).engagement,
    ).toBeUndefined();
  });

  test("skips disabled criteria so the writer is not billed for them", () => {
    const specs = defaultCriteriaSpecs().map((s) =>
      s.id === "pacing" ? { ...s, enabled: false } : s,
    );
    expect(buildRubricQuestions(specs).pacing).toBeUndefined();
    expect(buildRubricQuestions(specs).thesis).toBeDefined();
  });

  test("covers the shipped spine apart from engagement", () => {
    const questions = buildRubricQuestions(defaultCriteriaSpecs());
    const expected = SPINE_CRITERIA.filter((c) => c.id !== "engagement").length;
    expect(Object.keys(questions).length).toBe(expected);
  });

  test("includes the writer's own criteria", () => {
    const custom: RubricCriterionSpec = {
      id: "custom-1",
      label: "Second person",
      description: "Stays in second person throughout",
      source: "custom",
      enabled: true,
      weight: 1,
    };
    expect(
      buildRubricQuestions([...defaultCriteriaSpecs(), custom])["custom-1"],
    ).toBeDefined();
  });
});

describe("buildRubricState", () => {
  test("keeps the brief separate from the draft", () => {
    const state = buildRubricState({
      draft: "the draft",
      audience: "tax lawyers",
      goal: "persuade",
    });
    expect(state.draft).toBe("the draft");
    expect(state.audience).toBe("tax lawyers");
  });

  test("omits absent brief fields rather than sending empty strings", () => {
    expect(buildRubricState({ draft: "d" })).toEqual({ draft: "d" });
  });
});

describe("readRubricAnswers", () => {
  test("rescales levels onto the rubric's 0-10", () => {
    const grade = gradeOf({ thesis: answer(4, 0.9) });
    expect(grade.criteria.thesis.score).toBe(10);
    expect(grade.criteria.thesis.level).toBe(4);
  });

  test("keeps the whole distribution, not just the scalar", () => {
    const probabilities = { "0": 0.21, "1": 0.16, "2": 0.63 };
    const grade = gradeOf({ voice: answer(1.43, 0.14, probabilities) });
    expect(grade.criteria.voice.probabilities).toEqual(probabilities);
    expect(grade.criteria.voice.bimodal).toBe(true);
    expect(grade.criteria.voice.modal).toBe(2);
  });

  test("skips a non-Score answer rather than coercing it", () => {
    const grade = gradeOf({
      thesis: answer(3, 0.8),
      stray: { type: "noul", noul: 0.9 },
    });
    expect(grade.criteria.stray).toBeUndefined();
    expect(grade.criteria.thesis).toBeDefined();
  });

  test("records what the pass cost", () => {
    expect(gradeOf({ thesis: answer(2, 0.5) }).costUsd).toBeCloseTo(
      0.0000588,
      7,
    );
  });
});

describe("viewRubricGrade", () => {
  const grade = gradeOf({
    thesis: answer(4, 0.95), // 10/10, confident
    evidence: answer(0, 0.87), // 0/10, confident
    targetFit: answer(1.2, 0.43), // 3/10, unsure
  });
  const specs = defaultCriteriaSpecs();

  test("sorts scores into the writer's bands", () => {
    const views = viewRubricGrade(grade, specs);
    const byId = Object.fromEntries(views.map((v) => [v.id, v]));
    expect(byId.thesis.verdict).toBe("strong");
    expect(byId.evidence.verdict).toBe("weak");
  });

  test("flags the unsure criterion for escalation, not the confident ones", () => {
    const views = viewRubricGrade(grade, specs);
    const byId = Object.fromEntries(views.map((v) => [v.id, v]));
    // Confidence tracks objectivity: the subjective criterion is the one
    // worth spending a frontier call on.
    expect(byId.targetFit.escalate).toBe(true);
    expect(byId.thesis.escalate).toBe(false);
    expect(byId.evidence.escalate).toBe(false);
  });

  test("marks below-floor criteria instead of dropping them silently", () => {
    const views = viewRubricGrade(grade, specs, {
      ...DEFAULT_THRESHOLDS,
      confidenceFloor: 0.5,
    });
    const byId = Object.fromEntries(views.map((v) => [v.id, v]));
    expect(byId.targetFit).toBeDefined();
    expect(byId.targetFit.belowFloor).toBe(true);
    expect(byId.thesis.belowFloor).toBe(false);
  });

  test("omits criteria the writer disabled", () => {
    const disabled = specs.map((s) =>
      s.id === "thesis" ? { ...s, enabled: false } : s,
    );
    const ids = viewRubricGrade(grade, disabled).map((v) => v.id);
    expect(ids).not.toContain("thesis");
    expect(ids).toContain("evidence");
  });

  test("carries the writer's weight through for display", () => {
    const heavy = specs.map((s) =>
      s.id === "thesis" ? { ...s, weight: 2.5 } : s,
    );
    const view = viewRubricGrade(grade, heavy).find((v) => v.id === "thesis");
    expect(view?.weight).toBe(2.5);
  });

  /**
   * Verification step 11. This is the property the whole caching design exists
   * to protect: a threshold slider must re-render from the cached pass alone.
   * If this function ever becomes async or takes a client, a drag starts
   * firing network requests and costing money per pixel.
   */
  test("re-renders from cache alone when a threshold moves", () => {
    const frozen = JSON.stringify(grade);
    const strict = viewRubricGrade(grade, specs, {
      ...DEFAULT_THRESHOLDS,
      weakAtOrBelow: 9,
    });
    const loose = viewRubricGrade(grade, specs, {
      ...DEFAULT_THRESHOLDS,
      weakAtOrBelow: 0,
    });

    // Different output...
    expect(strict.find((v) => v.id === "thesis")?.verdict).toBe("weak");
    expect(loose.find((v) => v.id === "thesis")?.verdict).toBe("strong");
    // ...from an untouched cache.
    expect(JSON.stringify(grade)).toBe(frozen);
  });

  test("is synchronous, so a slider cannot await it", () => {
    expect(viewRubricGrade(grade, specs)).toBeInstanceOf(Array);
  });
});

describe("gradeScores", () => {
  test("feeds the existing weighted score without a second implementation", () => {
    const grade = gradeOf({ thesis: answer(4, 0.9), evidence: answer(2, 0.8) });
    expect(gradeScores(grade)).toEqual({ thesis: 10, evidence: 5 });
  });
});

describe("driftedKeys", () => {
  test("says nothing when the writer has not tuned anything", () => {
    expect(driftedKeys(DEFAULT_THRESHOLDS)).toEqual([]);
  });

  test("names each knob that has moved", () => {
    expect(
      driftedKeys({
        ...DEFAULT_THRESHOLDS,
        escalateBelow: 0.8,
        weakAtOrBelow: 2,
      }).sort(),
    ).toEqual(["escalateBelow", "weakAtOrBelow"]);
  });
});

import { describe, expect, test } from "bun:test";
import {
  confidenceOf,
  estimateCost,
  isBimodal,
  isNoul,
  isScore,
  modalLevel,
  noul,
  score,
  scoreOutOf,
  type ScoreAnswer,
} from "./system-one";

const scoreAnswer = (
  probabilities: Record<string, number>,
  value: number,
  confidence = 0.5,
): ScoreAnswer => ({
  type: "score",
  score: value,
  legend: Object.fromEntries(
    Object.keys(probabilities).map((k) => [k, `level ${k}`]),
  ),
  probabilities,
  confidence,
});

describe("isBimodal", () => {
  // The measured failure this function exists for: a real answer came back
  // score 1.43 at confidence 0.14 with mass piled on level 2, so the scalar
  // named the level the model thought *least* likely.
  test("catches the measured trough case", () => {
    const answer = scoreAnswer({ "0": 0.21, "1": 0.16, "2": 0.63 }, 1.43, 0.14);
    expect(isBimodal(answer)).toBe(true);
    expect(modalLevel(answer)).toBe(2);
  });

  test("a concentrated distribution is not bimodal", () => {
    expect(isBimodal(scoreAnswer({ "0": 0.05, "1": 0.9, "2": 0.05 }, 1.0))).toBe(
      false,
    );
  });

  test("a mild spread around the mean is not bimodal", () => {
    expect(
      isBimodal(scoreAnswer({ "0": 0.2, "1": 0.45, "2": 0.35 }, 1.15)),
    ).toBe(false);
  });

  test("modal level and nearest-to-mean agree when unimodal", () => {
    const answer = scoreAnswer({ "0": 0.1, "1": 0.7, "2": 0.2 }, 1.1);
    expect(modalLevel(answer)).toBe(Math.round(answer.score));
  });
});

describe("scoreOutOf", () => {
  test("maps the top level to the maximum", () => {
    const answer = scoreAnswer({ "0": 0, "1": 0, "2": 0, "3": 0, "4": 1 }, 4);
    expect(scoreOutOf(answer, 10)).toBe(10);
  });

  test("maps the bottom level to zero", () => {
    const answer = scoreAnswer({ "0": 1, "1": 0, "2": 0, "3": 0, "4": 0 }, 0);
    expect(scoreOutOf(answer, 10)).toBe(0);
  });

  test("scales by the declared level count, not a fixed assumption", () => {
    const threeLevel = scoreAnswer({ "0": 0, "1": 1, "2": 0 }, 1);
    const fiveLevel = scoreAnswer(
      { "0": 0, "1": 0, "2": 1, "3": 0, "4": 0 },
      2,
    );
    // Both are the middle level, so both are 5/10.
    expect(scoreOutOf(threeLevel, 10)).toBe(5);
    expect(scoreOutOf(fiveLevel, 10)).toBe(5);
  });
});

describe("confidence semantics", () => {
  test("a Noul carries no confidence", () => {
    expect(confidenceOf({ type: "noul", noul: 0.5 })).toBeNull();
  });

  test("a Score carries its distribution concentration", () => {
    expect(confidenceOf(scoreAnswer({ "0": 0.5, "1": 0.5 }, 0.5, 0.31))).toBe(
      0.31,
    );
  });
});

describe("type guards", () => {
  test("discriminate on the wire tag", () => {
    expect(isNoul({ type: "noul", noul: 0.2 })).toBe(true);
    expect(isScore({ type: "noul", noul: 0.2 })).toBe(false);
    expect(isScore(scoreAnswer({ "0": 1 }, 0))).toBe(true);
  });

  test("tolerate a missing answer", () => {
    expect(isScore(undefined)).toBe(false);
    expect(isNoul(undefined)).toBe(false);
  });
});

describe("builders", () => {
  test("noul carries no criteria", () => {
    expect(noul("ready?")).toEqual({ type: "noul", instructions: "ready?" });
  });

  test("score keeps criteria order, which is the level index", () => {
    const q = score("rate it", ["bad", "ok", "good"]);
    expect(q.criteria[0]).toBe("bad");
    expect(q.criteria[2]).toBe("good");
  });
});

describe("estimateCost", () => {
  // The measured full-spine pass: 1,401 input tokens for all 11 criteria.
  test("matches the measured rubric pass", () => {
    const cost = estimateCost({ input_tokens: 1401, output_tokens: 300 });
    expect(cost).toBeCloseTo(0.0000588, 7);
  });

  test("output tokens are free", () => {
    const a = estimateCost({ input_tokens: 1000, output_tokens: 0 });
    const b = estimateCost({ input_tokens: 1000, output_tokens: 100_000 });
    expect(a).toBe(b);
  });
});

/**
 * Helping the writer sharpen a brief, before it poisons everything downstream.
 *
 * The brief is the root input. `targetFit` grades the draft against its goal
 * and audience; the note gate vetoes advice that breaks its constraints;
 * triage weighs criticality against what the piece is trying to do. All three
 * inherit whatever vagueness the brief has. "General readers" and "make it
 * good" produce judgements that are perfectly well-formed and worth nothing,
 * and the writer has no way to see that the problem started here.
 *
 * So this grades the brief itself, field by field, and says which answers are
 * carrying weight and which are decoration.
 *
 * **What Jev can and cannot do here, stated plainly**, because it would be
 * easy to design past it: Jev does not generate text. It cannot write "your
 * audience is too broad — who specifically?" It can only score and classify.
 * Every hint in this module is therefore authored in code and selected by a
 * classification. That is a real limit, and it is also why the level
 * descriptions below are written as diagnoses rather than grades — the level a
 * field lands on *is* the explanation the writer gets.
 */

import type { ProjectBrief, ProjectInterviewAnswers } from "../types";
import {
  noul,
  choice as choiceQuestion,
  score as scoreQuestion,
  isScore,
  isChoice,
  isNoul,
  scoreOutOf,
  type SystemOneAnswer,
  type SystemOneQuestion,
} from "./system-one";

/* ── Field sufficiency ─────────────────────────────────────────── */

/**
 * Worst-first. The discriminator between "Specific" and "Sharp" is whether
 * the answer *excludes* anything: a brief answer that rules nothing out cannot
 * be failed by any draft, and a criterion no draft can fail is not a criterion.
 */
const SUFFICIENCY_LEVELS = [
  "Missing — there is nothing usable here",
  "Vague — this could describe almost any piece",
  "Partial — a direction, but the key decision is still open",
  "Specific — a writer could act on this without asking a follow-up",
  "Sharp — it rules things out, not just in",
];

/** The seven interview fields, with what each is actually for. */
const FIELD_PROMPTS: Record<keyof ProjectInterviewAnswers, string> = {
  workingTitle:
    "the working title — whether it says what the piece is about, rather than gesturing at a topic",
  format:
    "the format — whether the length, shape and venue are clear enough to write to",
  audience:
    "the audience — whether it identifies actual readers with particular prior knowledge, rather than a demographic",
  goal: "the goal — whether it says what the piece should accomplish, not merely what it should cover",
  tone: "the tone — whether it distinguishes this piece from a generically well-written one",
  constraints:
    "the constraints — whether a reader could check a draft against them and say yes or no",
  successSignal:
    "the success signal — whether it names something observable that would show the piece worked",
};

export const BRIEF_FIELDS = Object.keys(
  FIELD_PROMPTS,
) as (keyof ProjectInterviewAnswers)[];

/* ── Constraint interrogation ──────────────────────────────────── */

/**
 * "Is this a real non-negotiable?" — the question the writer asked for.
 *
 * It matters mechanically, not just editorially. The note gate vetoes any
 * persona note that breaks a constraint, so a *preference* recorded as a
 * constraint will silently suppress good advice, and an *uncheckable*
 * constraint will make the veto fire at random. Sorting these is what keeps
 * that gate honest.
 */
const CONSTRAINT_KINDS = [
  "hard", // external, not the writer's to relax
  "editorial", // the writer's firm choice
  "preference", // would rather, but the piece survives
  "uncheckable", // cannot tell whether a draft complies
] as const;

export type ConstraintKind = (typeof CONSTRAINT_KINDS)[number];

const CONSTRAINT_OPTIONS = [
  "Hard — imposed from outside (legal, contractual, platform, factual) and not the writer's to relax",
  "Editorial — the writer's own firm decision about what this piece is",
  "Preference — the writer would rather, but the piece still works if it is broken",
  "Uncheckable — no one could look at a draft and say whether it complies",
];

const CONSTRAINT_TO_KIND = new Map<string, ConstraintKind>(
  CONSTRAINT_OPTIONS.map((label, i) => [label, CONSTRAINT_KINDS[i]]),
);

/** One constraint per line or bullet; that is how writers actually type them. */
export function splitConstraints(text: string): string[] {
  return text
    .split(/\n+|(?:^|\s)[•·–—-]\s+|;\s*/)
    .map((s) => s.trim().replace(/^[-•·–—]\s*/, ""))
    .filter((s) => s.length > 3)
    .slice(0, 12);
}

/* ── Questions ─────────────────────────────────────────────────── */

export function buildBriefState(brief: ProjectBrief): Record<string, string> {
  const state: Record<string, string> = {};
  for (const field of BRIEF_FIELDS) {
    const value = brief.answers[field];
    if (value) state[field] = value;
  }
  // Attachments are part of the brief's information content: a thin `goal`
  // backed by three annotated sources is not the same as a thin goal alone.
  if (brief.attachments.length) {
    state.attachments = brief.attachments
      .map((a) => `${a.title}: ${a.why}`)
      .join("\n");
  }
  return state;
}

export function buildBriefQuestions(
  brief: ProjectBrief,
): Record<string, SystemOneQuestion> {
  const questions: Record<string, SystemOneQuestion> = {};

  for (const field of BRIEF_FIELDS) {
    if (!brief.answers[field]) continue;
    questions[`field_${field}`] = scoreQuestion(
      `Rate ${FIELD_PROMPTS[field]}.`,
      SUFFICIENCY_LEVELS,
    );
  }

  // The whole-brief question is deliberately not the mean of the fields. A
  // brief can have seven adequate answers and still not say what the piece is,
  // and the sum is the thing the writer actually needs to know about.
  questions.sufficient = noul(
    "Could a competent writer who has never spoken to this person produce the intended piece from this brief alone, without asking a follow-up question?",
  );
  questions.contradictory = noul(
    "Do any two parts of this brief pull against each other — for example a tone that fights the goal, or a constraint that makes the success signal unreachable?",
  );

  const constraintTexts = splitConstraints(brief.answers.constraints ?? "");
  for (let i = 0; i < constraintTexts.length; i++) {
    questions[`constraint_${i}`] = choiceQuestion(
      `The writer listed this as a constraint: "${constraintTexts[i]}". Which kind is it?`,
      CONSTRAINT_OPTIONS,
    );
  }

  return questions;
}

/* ── Results ───────────────────────────────────────────────────── */

export interface FieldAssessment {
  field: keyof ProjectInterviewAnswers;
  /** 0–10. */
  score: number;
  confidence: number;
  /** The level it landed on — this is the explanation shown to the writer. */
  diagnosis: string;
  /** Worth prompting the writer about. */
  needsWork: boolean;
}

export interface ConstraintAssessment {
  text: string;
  kind: ConstraintKind;
  confidence: number;
  /** True non-negotiables are the ones the note gate should veto on. */
  enforceable: boolean;
  hint: string;
}

export interface BriefAssessment {
  fields: FieldAssessment[];
  constraints: ConstraintAssessment[];
  /** Probability a stranger could write the piece from this brief. */
  sufficiency: number | null;
  /** Probability two parts of the brief pull against each other. */
  contradiction: number | null;
  /** Fields to prompt on, weakest first. */
  weakest: FieldAssessment[];
}

/** Below this a field is worth prompting about. */
const NEEDS_WORK_BELOW = 5;

/**
 * The hints. Authored here rather than generated, for the reason given at the
 * top of the file — Jev classifies, it does not write.
 */
const CONSTRAINT_HINTS: Record<ConstraintKind, string> = {
  hard: "A real non-negotiable. Advice that breaks it will be suppressed.",
  editorial:
    "Your call rather than an external rule — still enforced, but you can relax it if the piece needs it.",
  preference:
    "This reads as a preference. Left as a constraint it will suppress advice that might have been worth hearing; consider moving it to tone.",
  uncheckable:
    "No one could look at a draft and say whether this was met, so it cannot be enforced. Restate it as something observable.",
};

export function readBriefAssessment(
  brief: ProjectBrief,
  answers: Record<string, SystemOneAnswer>,
): BriefAssessment {
  const fields: FieldAssessment[] = [];
  for (const field of BRIEF_FIELDS) {
    const a = answers[`field_${field}`];
    if (!isScore(a)) continue;
    const score = scoreOutOf(a, 10);
    fields.push({
      field,
      score,
      confidence: a.confidence,
      diagnosis: a.legend[String(Math.round(a.score))] ?? "",
      needsWork: score < NEEDS_WORK_BELOW,
    });
  }

  const constraints: ConstraintAssessment[] = [];
  const constraintTexts = splitConstraints(brief.answers.constraints ?? "");
  for (let i = 0; i < constraintTexts.length; i++) {
    const text = constraintTexts[i];
    const a = answers[`constraint_${i}`];
    if (!isChoice(a)) continue;
    const kind = CONSTRAINT_TO_KIND.get(a.choice) ?? "editorial";
    constraints.push({
      text,
      kind,
      confidence: a.confidence,
      // Preferences and uncheckable statements must not drive the veto: the
      // first suppresses advice the writer would have wanted, the second fires
      // arbitrarily because there is nothing to check against.
      enforceable: kind === "hard" || kind === "editorial",
      hint: CONSTRAINT_HINTS[kind],
    });
  }

  const sufficientAnswer = answers.sufficient;
  const contradictoryAnswer = answers.contradictory;

  return {
    fields,
    constraints,
    sufficiency: isNoul(sufficientAnswer) ? sufficientAnswer.noul : null,
    contradiction: isNoul(contradictoryAnswer)
      ? contradictoryAnswer.noul
      : null,
    weakest: fields
      .filter((f) => f.needsWork)
      .sort((a, b) => a.score - b.score),
  };
}

/**
 * The constraints the note gate should actually enforce. Feeding it the raw
 * `constraints` string means enforcing preferences and uncheckable wishes
 * alike; this is the filtered set.
 */
export function enforceableConstraints(a: BriefAssessment): string[] {
  return a.constraints.filter((c) => c.enforceable).map((c) => c.text);
}

/**
 * Whether the brief is solid enough that downstream judgements mean anything.
 * When this is false, `targetFit` and the note-gate veto are measuring the
 * brief's vagueness rather than the draft's quality, and the honest move is to
 * say so instead of showing a confident-looking score.
 */
export function briefIsLoadBearing(a: BriefAssessment): boolean {
  if (a.sufficiency !== null && a.sufficiency < 0.4) return false;
  const graded = a.fields.filter((f) =>
    ["audience", "goal", "successSignal"].includes(f.field),
  );
  if (graded.length === 0) return false;
  return graded.every((f) => f.score >= NEEDS_WORK_BELOW);
}

/**
 * Deciding which parts of a draft deserve attention, and what kind.
 *
 * The room currently treats a draft as uniform: convene, and every persona
 * reads the whole thing. But a draft is not uniform — most paragraphs are
 * fine, a few are load-bearing, and one or two are quietly broken. Spending
 * the same frontier budget on each is why the room is slow and why its output
 * is padded with notes about paragraphs that did not need one.
 *
 * Triage fixes the allocation. One cheap pass marks every passage with what it
 * needs and how much the piece rests on it; the expensive passes then go only
 * where both are high. The gate in `note-gate.ts` handles the other end —
 * whether what came back was worth showing.
 *
 * Two engines answer the same question here, so the label set is defined once
 * and shared. Jev gives a calibrated distribution; Needle, running offline as
 * an enum classifier, gives a label and nothing else. Anything reading a
 * triage result must work when `confidence` is absent.
 */

import {
  noul,
  choice as choiceQuestion,
  isChoice,
  isNoul,
  type SystemOneAnswer,
  type SystemOneQuestion,
} from "./system-one";

/**
 * What a passage needs, in the writer's terms. These map onto surfaces Twyne
 * already has, which is the constraint that keeps the list honest — a label
 * with nowhere to go is a label that produces noise.
 */
export const TRIAGE_KINDS = [
  "nothing", // leave it alone
  "advice", // a specific change → persona note
  "question", // something only the writer can resolve → margin note
  "evidence", // a claim wanting a source → research target
  "cut", // the passage is not earning its space
] as const;

export type TriageKind = (typeof TRIAGE_KINDS)[number];

/** Phrasings the model picks between. Order matches `TRIAGE_KINDS`. */
const TRIAGE_OPTIONS = [
  "Nothing — this passage is fine as it stands",
  "Advice — a specific change would clearly improve it",
  "Question — something is ambiguous that only the writer can resolve",
  "Evidence — it makes a claim that wants a source",
  "Cut — it repeats, pads, or does not earn its space",
];

const OPTION_TO_KIND = new Map<string, TriageKind>(
  TRIAGE_OPTIONS.map((label, i) => [label, TRIAGE_KINDS[i]]),
);

/**
 * Keep a batch well inside the 64-question cap and the 32k state budget, and
 * chunk anything longer. A long essay costs several requests, which at
 * ~$0.00006 each is still not worth optimising.
 */
export const MAX_PASSAGES_PER_BATCH = 24;

/** Below this, a passage is a fragment — a heading, a one-line transition. */
const MIN_PASSAGE_CHARS = 80;

export interface Passage {
  id: string;
  text: string;
  /** Character offset in the draft, so a result can be mapped back. */
  from: number;
  to: number;
}

/**
 * Split on blank lines, which is how Tiptap serialises blocks, and drop the
 * fragments. Headings and one-line transitions are not passages a reader
 * stumbles on, and asking about them spends questions to learn "nothing".
 */
export function splitPassages(text: string): Passage[] {
  const passages: Passage[] = [];
  let offset = 0;
  let index = 0;
  for (const block of text.split(/\n{2,}/)) {
    const start = text.indexOf(block, offset);
    offset = start + block.length;
    const trimmed = block.trim();
    if (trimmed.length >= MIN_PASSAGE_CHARS) {
      passages.push({
        id: `p${index}`,
        text: trimmed,
        from: start,
        to: start + block.length,
      });
    }
    index += 1;
  }
  return passages;
}

/* ── Questions ─────────────────────────────────────────────────── */

/**
 * Each passage becomes its own `state` key, and two questions referring to it
 * by name. The full draft goes in alongside so "does this repeat something"
 * and "is this load-bearing" are answerable — neither is decidable from the
 * passage alone, which is the whole reason this is not a regex.
 */
export function buildTriageState(
  passages: Passage[],
  draft: string,
): Record<string, string> {
  const state: Record<string, string> = { draft };
  for (const p of passages) state[p.id] = p.text;
  return state;
}

export function buildTriageQuestions(
  passages: Passage[],
): Record<string, SystemOneQuestion> {
  const questions: Record<string, SystemOneQuestion> = {};
  for (const p of passages) {
    questions[`${p.id}_kind`] = choiceQuestion(
      `Considering ${p.id} in the context of the whole draft, what does it most need?`,
      TRIAGE_OPTIONS,
    );
    // Criticality is separate from need on purpose. A broken throwaway line
    // and a subtly weak thesis both come back as "advice"; only the second is
    // worth a frontier call, and nothing but this question distinguishes them.
    questions[`${p.id}_critical`] = noul(
      `Does the draft's central argument depend on ${p.id}? Answer yes only if weakening this passage would weaken the piece's main point.`,
    );
  }
  return questions;
}

/* ── Results ───────────────────────────────────────────────────── */

export interface TriagedPassage {
  passage: Passage;
  kind: TriageKind;
  /** Absent when Needle classified this offline. */
  confidence: number | null;
  /** Probability the argument rests on this passage. Absent offline. */
  criticality: number | null;
  /**
   * What to spend on this passage first. Need and criticality multiplied, so
   * a load-bearing weak spot outranks a broken aside.
   */
  priority: number;
}

/** `nothing` is the absence of need; everything else is worth something. */
function needWeight(kind: TriageKind, confidence: number | null): number {
  if (kind === "nothing") return 0;
  return confidence ?? 0.5;
}

export function readTriage(
  passages: Passage[],
  answers: Record<string, SystemOneAnswer>,
): TriagedPassage[] {
  const out: TriagedPassage[] = [];
  for (const passage of passages) {
    const kindAnswer = answers[`${passage.id}_kind`];
    if (!isChoice(kindAnswer)) continue;
    const kind = OPTION_TO_KIND.get(kindAnswer.choice) ?? "nothing";

    const criticalAnswer = answers[`${passage.id}_critical`];
    const criticality = isNoul(criticalAnswer) ? criticalAnswer.noul : null;

    out.push({
      passage,
      kind,
      confidence: kindAnswer.confidence,
      criticality,
      // Criticality defaults to 0.5 rather than 0 when unknown: an unscored
      // passage should sort among the middle, not be silently discarded.
      priority: needWeight(kind, kindAnswer.confidence) * (criticality ?? 0.5),
    });
  }
  return out.sort((a, b) => b.priority - a.priority);
}

/**
 * The passages worth spending a frontier call on. `budget` is the caller's,
 * not a constant here — the room knows how many personas it is about to fan
 * out to and what that costs.
 */
export function selectForAttention(
  triaged: TriagedPassage[],
  budget: number,
  minPriority = 0.25,
): TriagedPassage[] {
  return triaged
    .filter((t) => t.kind !== "nothing" && t.priority >= minPriority)
    .slice(0, budget);
}

/* ── Offline classification ────────────────────────────────────── */

/**
 * The same label set as a flat enum, for Needle's `extract()`. Needle cannot
 * generate, but it can pick from a closed set, which is exactly this problem
 * at lower fidelity: a label, no distribution, no criticality.
 *
 * Offline results carry `confidence: null` and `criticality: null`, so
 * `priority` collapses to a constant and the ordering is arbitrary. That is
 * the honest outcome — without a criticality signal there is no ranking to
 * make, and pretending otherwise would put a made-up number in front of the
 * writer.
 */
export const TRIAGE_ENUM = TRIAGE_KINDS as readonly string[];

export function triageFromLabels(
  passages: Passage[],
  labels: Record<string, string>,
): TriagedPassage[] {
  return passages.map((passage) => {
    const raw = labels[passage.id];
    const kind = (TRIAGE_KINDS as readonly string[]).includes(raw)
      ? (raw as TriageKind)
      : "nothing";
    return {
      passage,
      kind,
      confidence: null,
      criticality: null,
      priority: kind === "nothing" ? 0 : 0.5,
    };
  });
}

/**
 * Grading persona notes before the writer ever sees them.
 *
 * This inverts the usual ladder. Everywhere else the cheap engine answers
 * first and the expensive one is the escalation; here the expensive engine
 * answers and the cheap one decides whether the answer was any good. That
 * works because the two failures are asymmetric: a frontier model writing
 * vague, unactionable advice is common, and *recognising* vague advice is easy
 * — much easier than producing good advice in the first place.
 *
 * At ~$0.00006 per batched pass, gating every note costs less than the note
 * did by three orders of magnitude, so the gate is affordable even when it
 * rejects and forces a rewrite.
 *
 * The composition rule is deliberately not a weighted mean. Quality dimensions
 * average; the brief's constraints **veto**. A note can be the most helpful,
 * most actionable thing the room has ever produced and still be unusable
 * because the writer said "no second person" and it rewrites a line into
 * second person. Averaging those together would let helpfulness buy off a
 * constraint the writer declared non-negotiable, which is exactly backwards.
 */

import type { ProjectBrief } from "../types";
import {
  noul,
  score as scoreQuestion,
  isScore,
  isNoul,
  scoreOutOf,
  type SystemOneAnswer,
  type SystemOneQuestion,
} from "./system-one";

/** Quality dimensions, worst-first, as the writer would experience them. */
const HELPFUL_LEVELS = [
  "Useless — restates the draft or says nothing the writer did not know",
  "Vague — gestures at a problem without locating it",
  "Fair — names a real issue but shallowly",
  "Helpful — names a real issue and why it matters",
  "Incisive — names something the writer could not have seen alone",
];

const ACTIONABLE_LEVELS = [
  "Not actionable — the writer cannot tell what to change",
  "Barely — implies a direction but no concrete move",
  "Somewhat — a change is implied and could be inferred",
  "Actionable — a specific change to a specific place",
  "Immediately actionable — the writer could apply it without rereading",
];

const SERVES_GOAL_LEVELS = [
  "Works against the goal — following it would hurt the piece",
  "Irrelevant to the goal — true but beside the point",
  "Neutral — a general writing improvement",
  "Serves the goal — advances what this piece is trying to do",
  "Strongly serves the goal — moves the piece toward its success signal",
];

export const NOTE_DIMENSIONS = ["helpful", "actionable", "servesGoal"] as const;
export type NoteDimension = (typeof NOTE_DIMENSIONS)[number];

/* ── Questions ─────────────────────────────────────────────────── */

/**
 * Independent questions batch into one request and run in parallel, so all
 * five below cost roughly what one costs. They cannot see each other's
 * answers, which is fine — none of them needs to.
 */
export function buildNoteQuestions(opts: {
  /** Skip the constraint veto when the brief declares none. */
  hasConstraints: boolean;
  hasSuccessSignal: boolean;
}): Record<string, SystemOneQuestion> {
  const questions: Record<string, SystemOneQuestion> = {
    helpful: scoreQuestion(
      "Rate how helpful this note is to the writer, given the passage it is about and the draft it sits in.",
      HELPFUL_LEVELS,
    ),
    actionable: scoreQuestion(
      "Rate how actionable this note is: could the writer tell exactly what to change, and where?",
      ACTIONABLE_LEVELS,
    ),
    servesGoal: scoreQuestion(
      "Rate how well following this note would serve the stated goal of the piece for its stated audience.",
      SERVES_GOAL_LEVELS,
    ),
  };

  // A Noul, not a Score, because this is a yes/no fact about the brief rather
  // than a quality judgement. Asking it as a Score would invite the model to
  // rate *how badly* it violates, which is not a question anyone asked.
  if (opts.hasConstraints) {
    questions.violatesConstraints = noul(
      "Does following this note require breaking any of the writer's stated constraints? Answer yes only if the note is actually incompatible with a constraint, not merely unrelated to it.",
    );
  }
  if (opts.hasSuccessSignal) {
    questions.movesSuccessSignal = noul(
      "Would following this note make the piece more likely to produce the writer's stated success signal?",
    );
  }
  return questions;
}

export function buildNoteState(input: {
  note: string;
  quote: string;
  persona?: string;
  brief?: ProjectBrief | null;
  /** Surrounding draft, for whether the note is redundant with what's there. */
  draftExcerpt?: string;
}): Record<string, string> {
  const state: Record<string, string> = {
    note: input.note,
    passage: input.quote,
  };
  if (input.persona) state.advisor = input.persona;
  if (input.draftExcerpt) state.draft = input.draftExcerpt;

  const a = input.brief?.answers;
  if (a) {
    if (a.audience) state.audience = a.audience;
    if (a.goal) state.goal = a.goal;
    if (a.tone) state.tone = a.tone;
    if (a.constraints) state.constraints = a.constraints;
    if (a.successSignal) state.successSignal = a.successSignal;
  }
  return state;
}

/* ── Verdict ───────────────────────────────────────────────────── */

export interface NoteDimensionScore {
  /** 0–10. */
  score: number;
  confidence: number;
  /** The level description the score landed nearest — the rewrite feedback. */
  nearestLevel: string;
}

export interface NoteVerdict {
  dimensions: Partial<Record<NoteDimension, NoteDimensionScore>>;
  /** Mean of the graded dimensions, 0–10. */
  overall: number;
  /** Probability the note breaks a stated constraint. */
  violationRisk: number | null;
  /** Probability it moves the writer's success signal. */
  successSignal: number | null;
  /** Vetoed on constraints, regardless of quality. */
  vetoed: boolean;
  pass: boolean;
  /** Why it failed, in the writer's terms — also the rewrite instruction. */
  reasons: string[];
}

export interface NoteGateThresholds {
  /** Mean quality a note must reach. */
  minOverall: number;
  /** A single dimension this low sinks the note even if the mean is fine. */
  minDimension: number;
  /**
   * Veto above this probability of breaking a constraint. Not 0.5: a Noul at
   * 0.5 means *genuinely uncertain*, and discarding a note on a coin flip
   * throws away good advice. Err toward showing it and letting the writer
   * judge, because they are the one who wrote the constraint.
   */
  maxViolationRisk: number;
}

export const DEFAULT_NOTE_THRESHOLDS: NoteGateThresholds = {
  minOverall: 5,
  minDimension: 3,
  maxViolationRisk: 0.75,
};

function nearest(legend: Record<string, string>, level: number): string {
  return legend[String(Math.round(level))] ?? "";
}

export function readNoteVerdict(
  answers: Record<string, SystemOneAnswer>,
  thresholds: NoteGateThresholds = DEFAULT_NOTE_THRESHOLDS,
): NoteVerdict {
  const dimensions: Partial<Record<NoteDimension, NoteDimensionScore>> = {};
  for (const dim of NOTE_DIMENSIONS) {
    const a = answers[dim];
    if (!isScore(a)) continue;
    dimensions[dim] = {
      score: scoreOutOf(a, 10),
      confidence: a.confidence,
      nearestLevel: nearest(a.legend, a.score),
    };
  }

  const present = Object.values(dimensions);
  const overall = present.length
    ? present.reduce((s, d) => s + d.score, 0) / present.length
    : 0;

  const violation = answers.violatesConstraints;
  const violationRisk = isNoul(violation) ? violation.noul : null;
  const signal = answers.movesSuccessSignal;
  const successSignal = isNoul(signal) ? signal.noul : null;

  const vetoed =
    violationRisk !== null && violationRisk > thresholds.maxViolationRisk;

  const reasons: string[] = [];
  if (vetoed) {
    reasons.push("Conflicts with a constraint stated in the brief.");
  }
  for (const [dim, d] of Object.entries(dimensions) as [
    NoteDimension,
    NoteDimensionScore,
  ][]) {
    if (d.score < thresholds.minDimension) {
      // The level description, not the number: "Vague — gestures at a problem
      // without locating it" tells a model what to fix. "helpful: 2.1" does not.
      reasons.push(`${dim}: ${d.nearestLevel}`);
    }
  }
  if (!vetoed && overall < thresholds.minOverall && reasons.length === 0) {
    reasons.push("Below the quality bar overall without one clear weak spot.");
  }

  return {
    dimensions,
    overall,
    violationRisk,
    successSignal,
    vetoed,
    pass:
      !vetoed &&
      overall >= thresholds.minOverall &&
      present.every((d) => d.score >= thresholds.minDimension),
    reasons,
  };
}

/* ── Rewriting ─────────────────────────────────────────────────── */

/**
 * At most two retries. A model that has failed the same gate three times is
 * not going to pass it on the fourth; it has misread the passage, and burning
 * further frontier calls on it costs real money for no gain.
 */
export const MAX_REWRITES = 2;

/**
 * Turn a failed verdict into an instruction. Phrased as what to do rather than
 * what went wrong, because "be more specific about which sentence" produces a
 * better second attempt than "your note scored 2.1 on actionable".
 */
export function rewriteInstruction(verdict: NoteVerdict): string {
  const lines = ["Revise the note. It did not meet the bar:"];
  for (const reason of verdict.reasons) lines.push(`- ${reason}`);
  if (verdict.vetoed) {
    lines.push(
      "Rewrite so it respects the writer's stated constraints. If the point cannot be made without breaking one, drop it and make a different point about this passage.",
    );
  } else {
    lines.push(
      "Name the specific sentence or phrase, say what is wrong with it, and say what to do instead. Do not restate the passage.",
    );
  }
  return lines.join("\n");
}

/**
 * Keep the best attempt, not the last one. A rewrite can come back worse, and
 * having paid for both there is no reason to show the worse one. Vetoed
 * attempts always lose to un-vetoed ones regardless of score.
 */
export function bestAttempt<T>(
  attempts: { note: T; verdict: NoteVerdict }[],
): { note: T; verdict: NoteVerdict } | null {
  if (attempts.length === 0) return null;
  return attempts.reduce((best, a) => {
    if (best.verdict.vetoed !== a.verdict.vetoed) {
      return best.verdict.vetoed ? a : best;
    }
    return a.verdict.overall > best.verdict.overall ? a : best;
  });
}

