test("re-renders from cache alone when a threshold moves", () => {
  const frozen = JSON.stringify(grade);
  const strict = viewRubricGrade(grade, specs, {
    ...DEFAULT_THRESHOLDS,
    weakAtOrBelow: 9,
  });
  const loose = viewRubricGrade(grade, specs, {
    ...DEFAULT_THRESHOLDS,
    weakAtOrBelow: 0,
  });

  // Different output...
  expect(strict.find((v) => v.id === "thesis")?.verdict).toBe("weak");
  expect(loose.find((v) => v.id === "thesis")?.verdict).toBe("strong");
  // ...from an untouched cache.
  expect(JSON.stringify(grade)).toBe(frozen);
});

